<?php use App\Livewire\Admin\Dashboard as AdminDashboard; use App\Livewire\Admin\ManageAllOrders; use App\Livewire\Admin\ManageCategories; use App\Livewire\Admin\ManageStalls; use App\Livewire\Admin\ManageUsers; use App\Livewire\Public\MenuIndex; use App\Livewire\Public\MenuShow; use App\Livewire\Student\MyOrders; use App\Livewire\Vendor\ManageFoodItems; use App\Livewire\Vendor\ManageOrders; use App\Livewire\Vendor\ManageStall; use Illuminate\Support\Facades\Route; Route::get('/', fn () => redirect()->route('menu.index')); Route::get('/home', function () { return match (auth()->user()?->role) { 'admin' => redirect()->route('admin.dashboard'), 'vendor' => redirect()->route('vendor.orders.index'), default => redirect()->route('menu.index'), }; })->middleware('auth')->name('home'); Route::get('/menu', MenuIndex::class)->name('menu.index'); Route::get('/menu/{foodItem}', MenuShow::class)->name('menu.show'); Route::middleware(['auth', 'role:student'])->group(function () { Route::get('/orders', MyOrders::class)->name('orders.index'); }); Route::middleware(['auth', 'role:vendor'])->prefix('vendor')->name('vendor.')->group(function () { Route::get('/stall', ManageStall::class)->name('stall.show'); Route::get('/food-items', ManageFoodItems::class)->name('food-items.index'); Route::get('/orders', ManageOrders::class)->name('orders.index'); }); Route::middleware(['auth', 'role:admin'])->prefix('admin')->name('admin.')->group(function () { Route::get('/dashboard', AdminDashboard::class)->name('dashboard'); Route::get('/users', ManageUsers::class)->name('users.index'); Route::get('/stalls', ManageStalls::class)->name('stalls.index'); Route::get('/categories', ManageCategories::class)->name('categories.index'); Route::get('/orders', ManageAllOrders::class)->name('orders.index'); });